if($adminDataPage==='usuarios'){$raw=firebaseRead(fn(FirebaseReadService $f)=>$f->rtdb('usuarios'));if(is_array($raw))foreach($raw as $uid=>$data)if(is_array($data)){$data['_id']=(string)$uid;$records[]=$data;}}
elseif($adminDataPage==='dispensador'){$machine=firebaseRead(fn(FirebaseReadService $f)=>$f->rtdb('dispensador/principal'));if(!is_array($machine))$machine=[];}
