<main id="contenido" class="admin-page"><section class="admin-head"><div class="container"><div><span class="eyebrow eyebrow--light">Administración · Solo lectura</span><h1><?=h($titles[$adminDataPage]??'Datos')?></h1><p>Información operativa real de CHICHEJ. Las acciones de edición permanecen deshabilitadas.</p></div><a class="button button--outline-light" href="index.php">Volver al panel</a></div></section><section class="section section--cream"><div class="container"><?php if($adminDataPage==='dispensador'):?><div class="machine-live"><span class="status-pill status-pill--active">● Monitoreo RTDB</span><div class="admin-metrics"><article><span>Estado</span><strong><?=h($machine['estado']??'Sin datos')?></strong></article><article><span>Nivel</span><strong><?=isset($machine['nivelliquido'])?h($machine['nivelliquido']).'%':'Sin datos'?></strong><small>Distancia: <?=h($machine['distanciaCm']??'—')?> cm</small></article><article><span>Bomba</span><strong><?=h($machine['bomba']??'Sin datos')?></strong></article><article><span>Agitador</span><strong><?=h($machine['agitador']??'Sin datos')?></strong></article></div><div class="data-card"><h2>Producto actual</h2><p><?=h($machine['productoactual']??'Sin datos')?></p><button class="button button--ghost" disabled>Controles no disponibles en modo lectura</button></div></div><?php elseif(!$records):?><div class="empty-state"><span>◇</span><h2>Sin datos disponibles</h2><p>Firebase no devolvió registros para este módulo.</p></div><?php else:?><div class="data-list"><?php foreach($records as $r):?><article class="data-card"><div class="data-card__head"><div><small>ID <?=h($r['_id']??'Sin ID')?></small><h2><?php if($adminDataPage==='usuarios')echo h($r['nombre']??'Usuario');elseif($adminDataPage==='productos')echo h($r['nombre']??'Producto');elseif($adminDataPage==='pedidos')echo h($r['nombreUsuario']??'Pedido');elseif($adminDataPage==='reservas')echo h($r['nombreCliente']??'Reserva');else echo h($r['titulo']??'Publicación');?></h2></div><span><?=h($r['estado']??((isset($r['activo'])&&$r['activo']===true)?'Activo':'Solo lectura'))?></span></div><dl><?php if($adminDataPage==='usuarios'):?><div><dt>Email</dt><dd><?=h($r['email']??'Sin datos')?></dd></div><div><dt>Rol</dt><dd><?=h($r['rol']??'Sin datos')?></dd></div><div><dt>Bloqueado</dt><dd><?=($r['bloqueado']??false)===true?'Sí':'No'?></dd></div><div><dt>Registro</dt><dd><?=h(displayDate($r['fechaRegistro']??null))?></dd></div><?php elseif($adminDataPage==='productos'):?><div><dt>Presentación</dt><dd><?=h($r['cantidadMl']??'—')?> ml</dd></div><div><dt>Precio</dt><dd><?=h(money($r['precio']??null))?></dd></div><div><dt>Activo</dt><dd><?=($r['activo']??true)?'Sí':'No'?></dd></div><div><dt>Agotado</dt><dd><?=($r['agotado']??false)?'Sí':'No'?></dd></div><?php elseif($adminDataPage==='pedidos'):?><div><dt>Fecha</dt><dd><?=h(displayDate($r['fechaCreacion']??null))?></dd></div><div><dt>Productos</dt><dd><?=h(orderSummary($r))?></dd></div><div><dt>Total</dt><dd><?=h(money($r['total']??null))?></dd></div><div><dt>Pago</dt><dd><?=h($r['metodoPago']??'—')?> · <?=h($r['estadoPago']??'—')?></dd></div><div><dt>Origen</dt><dd><?=h(orderOrigin($r))?></dd></div><div><dt>Procesado</dt><dd><?=($r['procesado']??false)?'Sí':'No'?></dd></div><?php elseif($adminDataPage==='reservas'):?><div><dt>Usuario</dt><dd><?=h($r['usuarioId']??'Sin datos')?></dd></div><div><dt>Fecha</dt><dd><?=h(displayDate($r['fechaSolicitada']??null))?></dd></div><div><dt>Cantidad</dt><dd><?=h($r['cantidadSolicitada']??$r['cantidad']??'Sin datos')?></dd></div><div><dt>Lugar</dt><dd><?=h($r['lugarEvento']??'Sin datos')?></dd></div><?php else:?><div><dt>Tipo</dt><dd><?=h($r['tipo']??'informativo')?></dd></div><div><dt>Activo</dt><dd><?=($r['activo']??false)?'Sí':'No'?></dd></div><div><dt>Fecha</dt><dd><?=h(displayDate($r['fechaCreacion']??null))?></dd></div><div><dt>Mensaje</dt><dd><?=h($r['mensaje']??'')?></dd></div><?php endif;?></dl><button class="button button--ghost" disabled>Edición disponible en una fase futura</button></article><?php endforeach;?></div><?php endif;?></div></section></main>
